    #[test]
    fn capacity_eviction_prefers_idle_over_busy_even_if_more_recently_active() {
        let candidates = vec![
            capacity_candidate("idle-recent", true, &capacity_ts(1)),
            capacity_candidate("busy-older", false, &capacity_ts(100)),
        ];
        assert_eq!(
            select_live_capacity_eviction(&candidates, &HashSet::new()).as_deref(),
            Some("idle-recent"),
            "idle is preferred for eviction even over a busier-but-older session"
        );
    }

    #[test]
    fn capacity_eviction_prefers_oldest_last_active_among_idle() {
        let candidates = vec![
            capacity_candidate("idle-new", true, &capacity_ts(5)),
            capacity_candidate("idle-old", true, &capacity_ts(20)),
        ];
        assert_eq!(
            select_live_capacity_eviction(&candidates, &HashSet::new()).as_deref(),
            Some("idle-old")
        );
    }

    /// THE BUG FIX — a candidate with no readable `last_active` (empty: no
    /// meta, or a meta that never completed a turn) must be treated as the
    /// OLDEST (most evictable), never the newest. The prior `Instant`-based
    /// design treated its "no signal yet" case (`None`) as newest — correct
    /// for a session that TRULY just spawned, but also hit by every
    /// REBUILT/RESTORED session (daemon restart, cold `/use` resume), whose
    /// in-process clock resets to `None` regardless of how stale its real
    /// history was. That made a long-dormant-but-still-live session
    /// PERMANENTLY eviction-immune while genuinely-recent sessions were
    /// evicted around it. Reading `last_active` from disk (refreshed on every
    /// completed turn, survives restarts) fixes the common case; this test
    /// locks the remaining fallback to fail toward evictable, not immunity.
    #[test]
    fn capacity_eviction_treats_missing_last_active_as_oldest_not_newest() {
        let candidates = vec![
            capacity_candidate("has-recent-real-activity", true, &capacity_ts(10)),
            capacity_candidate("no-meta-signal", true, ""),
        ];
        assert_eq!(
            select_live_capacity_eviction(&candidates, &HashSet::new()).as_deref(),
            Some("no-meta-signal"),
            "a blank/unreadable last_active must be evicted BEFORE a session with real recent activity"
        );
    }

    #[test]
    fn capacity_eviction_falls_back_to_busy_oldest() {
        let candidates = vec![
            capacity_candidate("busy-new", false, &capacity_ts(2)),
            capacity_candidate("busy-old", false, &capacity_ts(30)),
        ];
        assert_eq!(
            select_live_capacity_eviction(&candidates, &HashSet::new()).as_deref(),
            Some("busy-old")
        );
    }

    #[test]
    fn capacity_eviction_respects_sid_and_hitl_exclusions() {
        let mut waiting = capacity_candidate("waiting", true, &capacity_ts(60));
        waiting.waiting_approval = true;
        let candidates = vec![
            waiting,
            capacity_candidate("parent", true, &capacity_ts(40)),
            capacity_candidate("eligible", true, &capacity_ts(10)),
        ];
        let excluded = HashSet::from(["parent".to_string()]);
        assert_eq!(
            select_live_capacity_eviction(&candidates, &excluded).as_deref(),
            Some("eligible")
        );
    }

    #[test]
    fn capacity_eviction_returns_none_when_all_candidates_are_excluded() {
        let candidates = vec![
            capacity_candidate("s1", true, &capacity_ts(0)),
            capacity_candidate("s2", false, ""),
        ];
        let excluded = HashSet::from(["s1".to_string(), "s2".to_string()]);
        assert_eq!(select_live_capacity_eviction(&candidates, &excluded), None);
    }

    #[tokio::test]
    async fn spawn_at_capacity_evicts_lru_idle_and_admits_new_session() {
        let tmp = tempfile::TempDir::new().unwrap();
        let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
        let mut gateway = Gateway::new(fake, "alpha", tmp.path());
        gateway.set_sessions_config(ccteam_core::SessionsConfig { max_live: 2 });

        let first = gateway
            .create_session_api(
                "alpha".into(),
                String::new(),
                AgentVendor::Claude,
                PermissionMode::Skip,
            )
            .await
            .unwrap()
            .sid;
        let second = gateway
            .create_session_api(
                "alpha".into(),
                String::new(),
                AgentVendor::Claude,
                PermissionMode::Skip,
            )
            .await
            .unwrap()
            .sid;
        gateway.sessions.get_mut(&second).unwrap().parent_sid = Some(first.clone());
        assert_eq!(
            gateway.live_capacity_exclusions("s3", Some(&second)),
            vec!["s3".to_string(), second.clone(), first.clone()]
        );
        gateway.sessions.get_mut(&second).unwrap().parent_sid = None;
        // Eviction ranks on the PERSISTED `meta.json.last_active` (not an
        // in-process clock — see `LiveCapacityCandidate`), so seed it on disk:
        // `first` older, `second` more recent.
        for (sid, secs_ago) in [(&first, 30i64), (&second, 5)] {
            let mut meta = read_session_meta(tmp.path(), sid).unwrap();
            meta.last_active =
                (chrono::Utc::now() - chrono::Duration::seconds(secs_ago)).to_rfc3339();
            write_session_meta(tmp.path(), &meta).unwrap();
        }

        let mut events = gateway.subscribe_events();
        let third = gateway
            .create_session_api(
                "alpha".into(),
                String::new(),
                AgentVendor::Claude,
                PermissionMode::Skip,
            )
            .await
            .unwrap()
            .sid;

        assert!(!gateway.sessions.contains_key(&first));
        assert!(gateway.sessions.contains_key(&second));
        assert!(gateway.sessions.contains_key(&third));
        assert_eq!(gateway.sessions.len(), 2);
        let event = events.recv().await.unwrap();
        assert_eq!(event.sid.as_deref(), Some(first.as_str()));
        assert!(matches!(
            event.kind,
            GatewayEventKind::SessionLifecycle { ref state, ref reason }
                if state == "evicted" && reason == "capacity"
        ));
    }

    // ── external ledger nodes (hand-started clients) ──────────────────────────

    /// A roleless managed session in project `alpha` — the foil every external
    /// node assertion below is measured against.
    async fn spawn_managed(gateway: &mut Gateway) -> String {
        gateway
            .create_session_api(
                "alpha".into(),
                String::new(),
                AgentVendor::Claude,
                PermissionMode::Skip,
            )
            .await
            .unwrap()
            .sid
    }

    /// A hand-started client joins ONE sid namespace: its node cannot collide
    /// with a managed spawn before or after it, and it lands a real `meta.json`
    /// marked external (which is what makes it a delegation parent instead of an
    /// anonymous caller whose children mount as roots).
    #[tokio::test]
    async fn external_node_gets_its_own_monotonic_sid_and_ledger_row() {
        use ccteam_harness::execution::session_meta::{session_meta_path, ManagedBy};

        let tmp = tempfile::TempDir::new().unwrap();
        let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
        let mut gateway = Gateway::new(fake, "alpha", tmp.path());

        let before = spawn_managed(&mut gateway).await;
        let node = gateway
            .register_external_node("alpha", "user:web-api", "codex/0.144.3")
            .unwrap();
        let after = spawn_managed(&mut gateway).await;
        assert_eq!(
            [before.as_str(), node.as_str(), after.as_str()],
            ["s1", "s2", "s3"],
            "one monotonic namespace shared with managed spawns"
        );

        let meta = read_session_meta(tmp.path(), &node).unwrap();
        assert_eq!(meta.managed_by, ManagedBy::External);
        assert!(!meta.managed_by.is_driveable());
        assert_eq!(meta.slug, "alpha");
        assert_eq!(
            meta.owner, "user:web-api",
            "identity comes from the credential"
        );
        assert_eq!(meta.vendor, AgentVendor::Codex, "vendor from clientInfo");
        assert!(meta.vendor_uuid.is_empty(), "no native session id is known");
        let raw = std::fs::read_to_string(session_meta_path(tmp.path(), &node)).unwrap();
        assert!(raw.contains("\"managed_by\": \"external\""), "{raw}");

        // The whole point: a ledger row WITHOUT a live-map row.
        assert!(!gateway.is_session_live(&node));
        assert!(gateway.is_external_node(&node));
        assert!(!gateway.is_external_node(&before));
        assert_eq!(gateway.external_node(&node).map(|m| m.sid), Some(node));
        assert!(gateway.external_node(&before).is_none());

        // An unregistered project is refused, and refusal burns no sid.
        assert!(gateway
            .register_external_node("nope", "user:web-api", "codex")
            .is_err());
        assert_eq!(spawn_managed(&mut gateway).await, "s4");
    }

    /// `driveable` is the one bit every consumer gates drive affordances on:
    /// true for a managed session, false for a client whose own operator drives
    /// it. The external row invents nothing it cannot observe.
    #[tokio::test]
    async fn session_views_marks_only_managed_sessions_driveable() {
        let tmp = tempfile::TempDir::new().unwrap();
        let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
        let mut gateway = Gateway::new(fake, "alpha", tmp.path());

        let managed = spawn_managed(&mut gateway).await;
        let node = gateway
            .register_external_node("alpha", "user:web-api", "codex/0.144.3")
            .unwrap();

        let views = gateway.session_views();
        assert_eq!(views.len(), 2, "one listing, both kinds of session");
        let m = views.iter().find(|v| v.sid == managed).unwrap();
        assert!(m.driveable);
        assert_eq!(m.status, "live");
        let n = views.iter().find(|v| v.sid == node).unwrap();
        assert!(!n.driveable);
        assert_eq!(n.project, "alpha");
        assert_eq!(n.vendor, "codex");
        assert!(n.role.is_empty(), "ccteam projected no role onto it");
        assert!(!n.current, "ccteam routes no chat to it");
        assert_eq!(n.status, "idle", "never claims to be working");
        assert_eq!(n.title.as_deref(), Some("codex/0.144.3"));
        assert!(!n.last_active.is_empty());
        assert!(
            n.last_activity_seconds.is_some(),
            "recency is derived from meta.last_active"
        );
        assert_eq!(
            (n.cost_usd, n.tokens_total, n.turn_count, n.waiting_approval),
            (None, None, 0, false),
            "no cost, token, turn or approval fabrication"
        );

        // A payload written before the field existed described a managed
        // session, so it must read back driveable.
        let legacy: SessionView = serde_json::from_str(
            r#"{"sid":"s9","project":"alpha","role":"","vendor":"claude","current":true,"status":"live"}"#,
        )
        .unwrap();
        assert!(legacy.driveable);
    }

    #[tokio::test]
    async fn repeated_session_views_do_not_read_live_session_meta_from_disk() {
        let tmp = tempfile::TempDir::new().unwrap();
        let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
        let mut gateway = Gateway::new(fake, "alpha", tmp.path());
        gateway.set_sessions_config(ccteam_core::SessionsConfig { max_live: 8 });
        for _ in 0..6 {
            spawn_managed(&mut gateway).await;
        }
        assert_eq!(gateway.session_views().len(), 6);
        let reads = gateway.session_catalog_disk_reads();

        for _ in 0..10 {
            let views = gateway.session_views();
            assert_eq!(views.len(), 6);
            assert!(views.iter().all(|view| !view.created_at.is_empty()));
        }
        assert_eq!(
            gateway.session_catalog_disk_reads(),
            reads,
            "catalog-backed live views must remain pure in-memory snapshots"
        );
    }

    /// The reason external nodes exist: a child spawned BY a hand-started agent
    /// hangs under it instead of mounting as a root. `session_list`'s tree is
    /// built purely from `parent_sid` over `session_views()`, and roots are rows
    /// whose parent is absent from the set — so both rows being present with the
    /// right linkage is exactly the tree property.
    #[tokio::test]
    async fn a_managed_child_stays_under_its_external_parent_in_session_views() {
        let tmp = tempfile::TempDir::new().unwrap();
        let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
        let mut gateway = Gateway::new(fake, "alpha", tmp.path());

        let parent = gateway
            .register_external_node("alpha", "user:web-api", "codex/0.144.3")
            .unwrap();
        let child = spawn_managed(&mut gateway).await;
        // The lineage `session_spawn` records for a delegated child.
        {
            let session = gateway.sessions.get_mut(&child).unwrap();
            session.parent_sid = Some(parent.clone());
            session.delegation_depth = 1;
        }

        let views = gateway.session_views();
        let p = views.iter().find(|v| v.sid == parent).unwrap();
        assert!(p.parent_sid.is_none(), "the node itself is a root");
        assert!(!p.driveable);
        let c = views.iter().find(|v| v.sid == child).unwrap();
        assert_eq!(c.parent_sid.as_deref(), Some(parent.as_str()));
        assert_eq!(c.delegation_depth, 1);
        assert!(c.driveable);
        let sids: HashSet<&str> = views.iter().map(|v| v.sid.as_str()).collect();
        assert!(
            sids.contains(parent.as_str()),
            "the child's parent is IN the set, so the tree nests it instead of \
             rooting it: {sids:?}"
        );
    }

    /// `DELETE` / idle sweep retires the node from the index only. Its
    /// `meta.json` stays, exactly like a stopped managed session's, so the
    /// delegation history of whatever it spawned still resolves.
    #[tokio::test]
    async fn close_external_node_removes_it_from_views_and_is_idempotent() {
        use ccteam_harness::execution::session_meta::ManagedBy;

        let tmp = tempfile::TempDir::new().unwrap();
        let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
        let mut gateway = Gateway::new(fake, "alpha", tmp.path());

        let node = gateway
            .register_external_node("alpha", "user:web-api", "codex/0.144.3")
            .unwrap();
        assert!(gateway.session_views().iter().any(|v| v.sid == node));

        assert!(gateway.close_external_node(&node));
        assert!(!gateway.session_views().iter().any(|v| v.sid == node));
        assert!(!gateway.is_external_node(&node));
        assert!(gateway.external_node(&node).is_none());
        assert!(
            !gateway.close_external_node(&node),
            "a second close is a no-op, not an error"
        );

        assert_eq!(
            read_session_meta(tmp.path(), &node).unwrap().managed_by,
            ManagedBy::External,
            "the ledger row survives the process"
        );
        assert_eq!(
            gateway.project_slug_for_sid(&node).as_deref(),
            Some("alpha"),
            "a retired node still resolves to its project (ACL + audit)"
        );
    }

    /// An external node is not a capacity subject in either direction: it never
    /// occupies a `max_live` slot (ccteam holds no thread) and is never picked
    /// for eviction (there is nothing to stop). Both follow from it not being in
    /// `sessions` — this is the fence for anyone tempted to merge the two maps.
    #[tokio::test]
    async fn an_external_node_is_never_a_capacity_eviction_candidate() {
        let tmp = tempfile::TempDir::new().unwrap();
        let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
        let mut gateway = Gateway::new(fake, "alpha", tmp.path());
        gateway.set_sessions_config(ccteam_core::SessionsConfig { max_live: 1 });

        let node = gateway
            .register_external_node("alpha", "user:web-api", "codex/0.144.3")
            .unwrap();
        let first = spawn_managed(&mut gateway).await;
        assert_eq!(
            gateway.sessions.len(),
            1,
            "the node did not consume the single live slot"
        );
        assert!(gateway.is_external_node(&node));

        // The next admission must take the managed session, never the node.
        let second = spawn_managed(&mut gateway).await;
        assert!(!gateway.sessions.contains_key(&first));
        assert!(gateway.sessions.contains_key(&second));
        assert!(
            gateway.is_external_node(&node),
            "an external node is never an eviction candidate"
        );
        assert_eq!(gateway.session_views().len(), 2, "node + admitted session");

        // The parent-chain protection walks straight through a non-live parent:
        // the external sid is listed (harmless — it is no candidate) and the
        // walk stops there instead of hunting it in `sessions`.
        assert_eq!(
            gateway.live_capacity_exclusions(&second, Some(&node)),
            vec![second.clone(), node.clone()]
        );
    }

    /// A cold start must not resurrect a hand-started client: its process died
    /// with the daemon, so its `meta.json` is audit, not a rebuild instruction —
    /// re-spawning a vendor in its place would mint a managed thread wearing
    /// another agent's sid. Covers both entries at once: the meta scan (the only
    /// restore source that can see external rows — `routing.json.live_sids`
    /// never held one) and the on-demand `/use` resume.
    #[tokio::test]
    async fn cold_start_and_resume_never_rebuild_an_external_node() {
        let tmp = tempfile::TempDir::new().unwrap();
        let project_dir = tmp.path().join("alpha");
        std::fs::create_dir_all(&project_dir).unwrap();

        let managed;
        let node;
        {
            // No persistence here on purpose: leaving routing.json absent is
            // what routes the restart through the meta.json recovery scan.
            let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
            let mut gateway = Gateway::new(fake, "alpha", &project_dir);
            managed = spawn_managed(&mut gateway).await;
            node = gateway
                .register_external_node("alpha", "user:web-api", "codex/0.144.3")
                .unwrap();
        }

        let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
        let mut restarted = Gateway::new(fake, "alpha", &project_dir);
        restarted.enable_persistence(tmp.path()).unwrap();
        assert_eq!(
            restarted.restore_pending,
            vec![managed.clone()],
            "only the managed session is rebuildable"
        );
        restarted.resume_restored_sessions().await;
        assert!(restarted.is_session_live(&managed));
        assert!(
            !restarted.is_external_node(&node),
            "the external index starts empty; the client re-enrolls if it returns"
        );
        assert!(!restarted.session_views().iter().any(|v| v.sid == node));
        assert!(
            read_session_meta(&project_dir, &node).is_ok(),
            "the ledger row stays on disk as audit"
        );

        // Same line at the on-demand entry (`plan_session_rebuild` is the shared
        // choke point for every rebuild path).
        let err = restarted
            .resume_stopped_session(&node, "web:web-api:web-api", None)
            .await
            .unwrap_err();
        assert!(err.to_string().contains("external"), "got: {err}");
        assert!(!restarted.is_session_live(&node), "nothing was spawned");
    }

    // ─────────────── one sid, one body (2026-08-19) ───────────────

    /// Spawn a `sleep` carrying `CCTEAM_CHAT_SID=<sid>` and record it as the
    /// sid's body: a process that "outlived the previous daemon".
    fn plant_body(project_dir: &std::path::Path, sid: &str) -> std::process::Child {
        let child = std::process::Command::new("sleep")
            .arg("60")
            .env(ccteam_harness::execution::session_body::BODY_SID_ENV, sid)
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("spawn sleep");
        ccteam_harness::execution::session_body::record(project_dir, sid, Some(child.id()), "test")
            .unwrap();
        child
    }

    fn body_gone(child: &mut std::process::Child) {
        let _ = child.kill();
        let _ = child.wait();
    }

    /// The restore after a daemon restart finds the session's body still
    /// running: it does NOT spawn a twin (zero `start_thread`), keeps the chat's
    /// focus on the sid, lists it as `detached`, queues a turn behind it, and —
    /// once the body has exited — rebuilds the session by sid and drains the
    /// queue on the very next watcher tick.
    #[tokio::test]
    async fn restart_waits_for_a_live_body_instead_of_spawning_a_twin() {
        let tmp = tempfile::TempDir::new().unwrap();
        let project_dir = tmp.path().join("alpha");
        std::fs::create_dir_all(&project_dir).unwrap();
        let chat = web_api_chat();

        let sid;
        {
            let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
            let mut gateway = Gateway::new(fake, "alpha", &project_dir);
            gateway.enable_persistence(tmp.path()).unwrap();
            sid = spawn_managed(&mut gateway).await;
            gateway
                .current_session
                .write()
                .unwrap()
                .insert(chat.clone(), sid.clone());
            gateway.persist_routing().unwrap();
        }
        // The previous daemon is gone; its body is not.
        let mut child = plant_body(&project_dir, &sid);

        let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
        let mut restarted = Gateway::new(fake.clone(), "alpha", &project_dir);
        restarted.enable_persistence(tmp.path()).unwrap();
        assert_eq!(restarted.restore_pending, vec![sid.clone()]);
        restarted.resume_restored_sessions().await;

        assert!(!restarted.is_session_live(&sid), "no twin is spawned");
        assert!(restarted.is_session_detached(&sid));
        assert_eq!(fake.starts.load(Ordering::SeqCst), 0, "zero start_thread");
        assert_eq!(
            restarted.current_session.read().unwrap().get(&chat),
            Some(&sid),
            "the chat keeps its focus on the detached sid"
        );
        let views = restarted.session_views();
        let row = views.iter().find(|v| v.sid == sid).expect("listed");
        assert_eq!(row.status, "detached");
        assert!(!row.driveable);
        assert_eq!(row.detached.as_ref().map(|d| d.pid), Some(child.id()));

        // A turn queues behind the body instead of spawning.
        let id = restarted
            .submit_to_sid(&sid, "hello after restart".into())
            .await
            .unwrap();
        assert!(id.starts_with("queued-behind-body:"), "got {id}");
        assert_eq!(
            crate::pending_turns::pending_turn_count(&project_dir, &sid),
            1
        );
        assert_eq!(fake.starts.load(Ordering::SeqCst), 0, "still no twin");
        // The IM leg gets the receipt as its reply.
        let replies = restarted
            .submit_to_current(&chat, "", "second message".into())
            .await
            .unwrap();
        assert!(
            replies.iter().any(|r| r.contains("queued")),
            "receipt explains the queue: {replies:?}"
        );
        assert_eq!(
            crate::pending_turns::pending_turn_count(&project_dir, &sid),
            2
        );
        // A directive cannot run on a detached body — a readable refusal.
        let err = restarted
            .submit_to_sid(&sid, "/model opus".into())
            .await
            .unwrap_err();
        assert!(is_body_detached_error(&err), "got {err}");

        // The body exits; the watcher rebuilds by sid and drains the queue.
        body_gone(&mut child);
        let gateway = Arc::new(tokio::sync::Mutex::new(restarted));
        Gateway::body_watch_tick(&gateway).await;
        let g = gateway.lock().await;
        assert!(
            g.is_session_live(&sid),
            "rebuilt by sid after the body exited"
        );
        assert!(!g.is_session_detached(&sid));
        assert_eq!(fake.starts.load(Ordering::SeqCst), 1, "exactly one body");
        assert_eq!(
            crate::pending_turns::pending_turn_count(&project_dir, &sid),
            0,
            "queue drained into the rebuilt session"
        );
        let submitted: Vec<String> = fake
            .submissions
            .lock()
            .await
            .iter()
            .map(|(_, text)| text.clone())
            .collect();
        assert_eq!(
            submitted,
            vec![
                "hello after restart".to_string(),
                "second message".to_string()
            ]
        );
        assert_eq!(
            ccteam_harness::execution::session_body::probe(&project_dir, &sid),
            ccteam_harness::execution::session_body::BodyProbe::Absent,
            "the old record is gone; the new body's record is the fake's business"
        );
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn body_exit_pending_submit_does_not_hold_the_gateway_registry() {
        use std::os::fd::AsRawFd;

        let tmp = tempfile::TempDir::new().unwrap();
        let project_dir = tmp.path().join("alpha");
        std::fs::create_dir_all(&project_dir).unwrap();
        let sid;
        {
            let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
            let mut gateway = Gateway::new(fake, "alpha", &project_dir);
            gateway.enable_persistence(tmp.path()).unwrap();
            sid = spawn_managed(&mut gateway).await;
        }
        let mut body = plant_body(&project_dir, &sid);
        let submit = Arc::new(TestStartBarrier::default());
        let fake = Arc::new(
            FakeAdapter::new(AgentVendor::Claude).with_submit_barrier(Arc::clone(&submit)),
        );
        let mut restarted = Gateway::new(fake, "alpha", &project_dir);
        restarted.enable_persistence(tmp.path()).unwrap();
        restarted.resume_restored_sessions().await;
        let gateway = Arc::new(tokio::sync::Mutex::new(restarted));

        // Hold the pending module's stable sibling lock so the enqueue's
        // spawn_blocking worker stops inside durable storage. The unrelated
        // gateway registry must remain immediately observable.
        let lock_path = project_dir
            .join(".ccteam")
            .join("chat")
            .join(&sid)
            .join(".pending_turns.lock");
        std::fs::create_dir_all(lock_path.parent().unwrap()).unwrap();
        let lock_file = std::fs::OpenOptions::new()
            .create(true)
            .truncate(false)
            .read(true)
            .write(true)
            .open(&lock_path)
            .unwrap();
        assert_eq!(
            unsafe { libc::flock(lock_file.as_raw_fd(), libc::LOCK_EX) },
            0
        );
        let queue_gateway = Arc::clone(&gateway);
        let queue_sid = sid.clone();
        let queue = tokio::spawn(async move {
            Gateway::submit_to_sid_shared(
                queue_gateway,
                &queue_sid,
                "queued while detached".into(),
                GatewayDeadline::start(),
            )
            .await
        });
        tokio::time::sleep(std::time::Duration::from_millis(30)).await;
        assert!(
            !queue.is_finished(),
            "enqueue must be waiting on durable lock"
        );
        assert_other_chat_observability_is_prompt(&gateway).await;
        assert_eq!(
            unsafe { libc::flock(lock_file.as_raw_fd(), libc::LOCK_UN) },
            0
        );
        queue.await.unwrap().unwrap();

        body_gone(&mut body);
        submit.arm();
        let tick_gateway = Arc::clone(&gateway);
        let tick = tokio::spawn(async move { Gateway::body_watch_tick(&tick_gateway).await });
        submit.wait_until_entered(1).await;

        assert_other_chat_observability_is_prompt(&gateway).await;
        submit.release_all();
        tick.await.unwrap();
    }

    /// `/stop` / `session_stop` / project stop on a detached sid ENDS the body
    /// (the one case the daemon signals such a process — on the user's word)
    /// and forgets it; the sid is then a plain stopped session.
    #[tokio::test]
    async fn explicit_stop_ends_a_detached_body() {
        let tmp = tempfile::TempDir::new().unwrap();
        let project_dir = tmp.path().join("alpha");
        std::fs::create_dir_all(&project_dir).unwrap();
        let sid;
        {
            let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
            let mut gateway = Gateway::new(fake, "alpha", &project_dir);
            gateway.enable_persistence(tmp.path()).unwrap();
            sid = spawn_managed(&mut gateway).await;
        }
        let mut child = plant_body(&project_dir, &sid);
        let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
        let mut restarted = Gateway::new(fake.clone(), "alpha", &project_dir);
        restarted.enable_persistence(tmp.path()).unwrap();
        restarted.resume_restored_sessions().await;
        assert!(restarted.is_session_detached(&sid));
        let pid = child.id();

        restarted.stop_session(&sid).await.unwrap();
        assert!(!restarted.is_session_detached(&sid));
        assert!(!restarted.is_session_live(&sid));
        // The process is gone (reap it so the assertion is about the kill,
        // not a zombie).
        let status = child.wait().expect("stopped body is waitable");
        assert!(
            !status.success() || status.code().is_none(),
            "signalled: {status:?}"
        );
        assert!(!ccteam_harness::execution::session_body::body_is_alive(
            &ccteam_harness::execution::session_body::SessionBody {
                pid,
                fingerprint: String::new(),
                adapter: String::new(),
                recorded_at: String::new(),
            },
            &sid
        ));
        assert_eq!(
            ccteam_harness::execution::session_body::probe(&project_dir, &sid),
            ccteam_harness::execution::session_body::BodyProbe::Absent
        );
        // A later turn cold-resumes the sid like any stopped session (a fresh
        // body, no queue).
        let id = restarted
            .submit_to_sid(&sid, "after stop".into())
            .await
            .unwrap();
        assert!(!id.starts_with("queued-behind-body:"), "got {id}");
        assert_eq!(fake.starts.load(Ordering::SeqCst), 1);
    }

    /// A body record whose process is already GONE at restore time means the
    /// body finished (or died) while no daemon was watching. The session is
    /// rebuilt at once; the watcher's post-mortem then reports the unanswered
    /// prompt honestly (the fake vendor keeps no recoverable record): an
    /// `unobserved` row in the mirror, an Answer to the reply target, and a
    /// boundary signal so a delegation parent does not keep waiting.
    #[tokio::test]
    async fn stale_body_record_reports_the_unobserved_turn() {
        let tmp = tempfile::TempDir::new().unwrap();
        let project_dir = tmp.path().join("alpha");
        std::fs::create_dir_all(&project_dir).unwrap();
        let sid;
        {
            let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
            let mut gateway = Gateway::new(fake, "alpha", &project_dir);
            gateway.enable_persistence(tmp.path()).unwrap();
            sid = spawn_managed(&mut gateway).await;
        }
        // The prompt ccteam delivered but never saw answered.
        ccteam_harness::execution::turns_mirror::append_turn(
            &project_dir,
            &sid,
            &ccteam_harness::execution::turns_mirror::TurnRecord {
                turn_id: "t-open".into(),
                ts: chrono::Utc::now(),
                vendor: "claude".into(),
                role: String::new(),
                user: "finish the task".into(),
                assistant: String::new(),
                usage: serde_json::Value::Null,
                tool_calls: Vec::new(),
                attachments: Vec::new(),
                outcome: None,
                error_kind: None,
                error: None,
            },
        )
        .unwrap();
        // A body that already exited unobserved.
        let mut child = plant_body(&project_dir, &sid);
        body_gone(&mut child);

        let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
        let mut restarted = Gateway::new(fake.clone(), "alpha", &project_dir);
        restarted.enable_persistence(tmp.path()).unwrap();
        let (dtx, mut drx) = tokio::sync::mpsc::unbounded_channel();
        restarted.set_delegation_notifier_tx(dtx);
        let mut events = restarted.subscribe_events();
        restarted.resume_restored_sessions().await;
        assert!(
            restarted.is_session_live(&sid),
            "rebuilt at once: nothing to wait for"
        );
        assert!(!restarted.is_session_detached(&sid));
        assert_eq!(restarted.post_mortem_pending.len(), 1);

        let gateway = Arc::new(tokio::sync::Mutex::new(restarted));
        Gateway::body_watch_tick(&gateway).await;
        assert!(gateway.lock().await.post_mortem_pending.is_empty());

        let turns =
            ccteam_harness::execution::turns_mirror::read_all_turns(&project_dir, &sid).unwrap();
        let last = turns.last().expect("a post-mortem row");
        assert_eq!(last.outcome.as_deref(), Some("unobserved"));
        assert_eq!(last.error_kind.as_deref(), Some("body_unobserved"));

        let answer = tokio::time::timeout(std::time::Duration::from_secs(2), async {
            loop {
                let ev = events.recv().await.expect("broadcast open");
                if matches!(ev.kind, GatewayEventKind::Answer) && ev.sid.as_deref() == Some(&sid) {
                    return ev;
                }
            }
        })
        .await
        .expect("the reply target is told");
        assert!(
            answer.content.contains("could not be recovered"),
            "{}",
            answer.content
        );

        let signal = drx
            .try_recv()
            .expect("boundary signal for the delegation notifier");
        assert_eq!(signal.child_sid, sid);
        assert!(signal.boundary);
        assert!(
            signal.vendor_error,
            "an unanswered task is reported as not-ok"
        );
    }

    /// Seed a `.claude/agents/<role>.md` under `project_dir` so the `/role`
    /// existence check (`ccteam_core::read_role`) resolves it. Minimal frontmatter
    /// is enough; the gateway only checks the file exists, not its contents.
    fn seed_role(project_dir: &std::path::Path, role: &str) {
        seed_role_with_model(project_dir, role, None);
    }

    fn seed_role_with_model(project_dir: &std::path::Path, role: &str, model: Option<&str>) {
        let agents = project_dir.join(".claude").join("agents");
        std::fs::create_dir_all(&agents).unwrap();
        let model = model.map(|m| format!("model: {m}\n")).unwrap_or_default();
        std::fs::write(
            agents.join(format!("{role}.md")),
            format!("---\nname: {role}\n{model}---\n{role} role.\n"),
        )
        .unwrap();
    }

    /// Poll a [`Gateway::subscribe_events`] receiver for the next `Answer`
    /// event, skipping any `Reaction`/`Progress` noise in between. Bounded so
    /// a real regression (the pump never sends) fails the test instead of
    /// hanging.
    async fn recv_answer(
        events: &mut tokio::sync::broadcast::Receiver<GatewayEvent>,
    ) -> GatewayEvent {
        tokio::time::timeout(std::time::Duration::from_secs(5), async {
            loop {
                let ev = events.recv().await.expect("broadcast tee still open");
                if matches!(ev.kind, GatewayEventKind::Answer) {
                    return ev;
                }
            }
        })
        .await
        .expect("an Answer event arrives")
    }

    async fn recv_sink_answers(
        events: &mut tokio::sync::mpsc::UnboundedReceiver<GatewayEvent>,
        count: usize,
    ) -> Vec<GatewayEvent> {
        tokio::time::timeout(std::time::Duration::from_secs(5), async {
            let mut answers = Vec::new();
            while answers.len() < count {
                let event = events.recv().await.expect("gateway sink remains open");
                if matches!(event.kind, GatewayEventKind::Answer) {
                    answers.push(event);
                }
            }
            answers
        })
        .await
        .expect("expected Answer events arrive")
    }

    async fn wait_for_turn_idle(gateway: &Gateway, sid: &str) {
        for _ in 0..100 {
            if !gateway.session_turn_in_flight(sid) {
                tokio::task::yield_now().await;
                return;
            }
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        }
        panic!("turn {sid} did not reach its boundary");
    }

    /// Register `slug` in the catalog with a persisted `ProjectState.owner`.
    /// Ownership is what a tenant's visibility is computed from, so any fixture
    /// that drives a NON-operator chat has to say which project it owns —
    /// otherwise the principal correctly resolves to "no project" and cannot
    /// spawn (`current_project_for`).
    fn seed_owned_project(paths: &ccteam_core::CcteamPaths, slug: &str, owner: Option<&str>) {
        let dir = paths.projects_root.join(slug);
        std::fs::create_dir_all(dir.join(".ccteam")).unwrap();
        let mut state = ccteam_core::ProjectState::initial(slug.to_string());
        state.owner = owner.map(str::to_string);
        state
            .save(&ccteam_core::CcteamPaths::project_state_in(&dir))
            .unwrap();
        ccteam_core::config::upsert_project(
            &paths.root,
            ccteam_core::ProjectEntry {
                slug: slug.to_string(),
                path: dir,
                host: ccteam_core::LOCAL_HOST.to_string(),
                remote_slug: None,
                remote_path: None,
                team: "dev".to_string(),
                installed_at: chrono::Utc::now(),
            },
        )
        .unwrap();
    }

    fn mirror_test_paths(tmp: &tempfile::TempDir) -> (CcteamPaths, PathBuf) {
        let paths = CcteamPaths {
            root: tmp.path().join("home"),
            projects_root: tmp.path().join("projects"),
        };
        let project_dir = paths.projects_root.join("alpha");
        std::fs::create_dir_all(&project_dir).unwrap();
        (paths, project_dir)
    }

    fn seed_global_telegram(paths: &CcteamPaths, allowed_chat_ids: Vec<String>) {
        crate::credentials::save(
            &paths.im_credentials_path(),
            &crate::credentials::Credentials {
                telegram: Some(crate::credentials::TelegramCreds {
                    bot_token: "123:test".into(),
                    allowed_chat_ids,
                }),
                ..Default::default()
            },
        )
        .unwrap();
    }

