    /// v0.8.24 F5 — when `thread_is_live` is false, `submit_resolved` must
    /// **enqueue** the user text (production path calls `enqueue_pending_turn`)
    /// before resume, then drain FIFO after the child is live. Pre-seeded
    /// pending turns + the just-enqueued one both land, in order.
    #[tokio::test]
    async fn submit_while_not_live_enqueues_then_drains_fifo() {
        let tmp = tempfile::TempDir::new().unwrap();
        let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
        let mut gateway = Gateway::new(fake.clone(), "alpha", tmp.path());

        let sid = gateway
            .create_session_api(
                "alpha".into(),
                "reviewer".into(),
                AgentVendor::Claude,
                ccteam_harness::PermissionMode::Skip,
            )
            .await
            .unwrap();
        assert_eq!(sid, "s1");
        assert_eq!(fake.starts.load(Ordering::SeqCst), 1);

        // Cold-start queue already has one turn (e.g. concurrent web POST
        // while the child was still spawning).
        crate::pending_turns::enqueue_pending_turn(
            tmp.path(),
            &sid,
            "queued-first",
            Some("web".into()),
            false,
            false,
            false,
        )
        .unwrap();
        assert_eq!(
            crate::pending_turns::pending_turn_count(tmp.path(), &sid),
            1
        );

        // Child dies; next user turn must enqueue (not drop) then revive + drain.
        fake.live.store(false, Ordering::SeqCst);
        let turn = gateway
            .submit_to_sid(&sid, "queued-second".into())
            .await
            .unwrap();
        assert!(
            turn.starts_with("turn-alpha-reviewer-s1"),
            "drain surfaces the real turn id, got {turn}"
        );
        assert_eq!(
            fake.starts.load(Ordering::SeqCst),
            2,
            "resume re-started the dead child"
        );
        assert!(fake.live.load(Ordering::SeqCst));
        assert_eq!(
            crate::pending_turns::pending_turn_count(tmp.path(), &sid),
            0,
            "queue drained after live"
        );
        assert_eq!(
            fake.submissions.lock().await.as_slice(),
            &[
                ("alpha-reviewer-s1".to_string(), "queued-first".to_string()),
                ("alpha-reviewer-s1".to_string(), "queued-second".to_string()),
            ],
            "FIFO: pre-queued then just-enqueued"
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn aborted_pending_drain_keeps_cleanup_owned_ack_and_registry_responsive() {
        let tmp = tempfile::TempDir::new().unwrap();
        let submit = Arc::new(TestStartBarrier::default());
        let fake = Arc::new(
            FakeAdapter::new(AgentVendor::Claude).with_submit_barrier(Arc::clone(&submit)),
        );
        let mut gateway = Gateway::new(fake.clone(), "alpha", tmp.path());
        let sid = gateway
            .create_session_api(
                "alpha".into(),
                "reviewer".into(),
                AgentVendor::Claude,
                ccteam_harness::PermissionMode::Skip,
            )
            .await
            .unwrap()
            .sid;
        crate::pending_turns::enqueue_pending_turn(
            tmp.path(),
            &sid,
            "survive drain caller abort",
            Some("web".into()),
            false,
            false,
            false,
        )
        .unwrap();
        let gateway = Arc::new(Mutex::new(gateway));
        submit.arm();
        let drain_gateway = Arc::clone(&gateway);
        let drain_sid = sid.clone();
        let drain = tokio::spawn(async move {
            Gateway::drain_and_dispatch_pending_turns_shared(drain_gateway, &drain_sid).await
        });
        submit.wait_until_entered(1).await;

        assert_other_chat_observability_is_prompt(&gateway).await;
        assert_eq!(
            crate::pending_turns::pending_turn_count(tmp.path(), &sid),
            1,
            "claim is a durable fence, not a destructive drain"
        );
        drain.abort();
        let _ = drain.await;
        submit.release_all();
        Gateway::drain_cleanup_tasks_shared(&gateway).await;
        assert_eq!(fake.submissions.lock().await.len(), 1);
        assert_eq!(
            crate::pending_turns::pending_turn_count(tmp.path(), &sid),
            0,
            "cleanup-owned worker acknowledges after accepted submit"
        );
    }

