    /// Session buttons retain Telegram's eight-button row bound.
    #[test]
    fn session_buttons_have_at_most_eight_entries_per_row() {
        let reply = im_views::render_sessions(&SessionsView {
            project: "alpha".into(),
            sessions: (1..=9)
                .map(|index| SessionRow {
                    sid: format!("s{index}"),
                    vendor_model: "claude.—".into(),
                    // R2-4/R2-2 (2nd) — `status` is a RAW activity
                    // classification (`working`/`idle`/`stale`/`stuck`),
                    // rendered through `activity_badge`, not a pre-rendered
                    // display string; the pre-§3.5b `"🟢 ожидание"` literal
                    // used to silently render `⚪ неизвестно` here without
                    // this test (which only counts button-row lengths)
                    // ever noticing.
                    status: "idle".into(),
                    context: "—".into(),
                    title: None,
                    current: false,
                    tree_depth: 0,
                    host: None,
                })
                .collect(),
            elsewhere: 0,
            detached: Vec::new(),
        });
        assert_eq!(
            reply.button_rows.iter().map(Vec::len).collect::<Vec<_>>(),
            vec![2; 10]
        );
        assert!(reply
            .button_rows
            .iter()
            .flatten()
            .all(|button| button.data.len() <= 64));
        // R2-4 — the fixture claims every session is `idle`; assert the
        // rendered state actually says so (🟢 ожидание, never the `⚪
        // неизвестно` fallback an un-migrated display-string `status` would
        // silently produce), so a future regression back to a display
        // string can't hide behind a test that only counts button rows.
        assert!(
            reply.markdown.matches("🟢").count() >= 9,
            "{}",
            reply.markdown
        );
        assert!(!reply.markdown.contains('⚪'), "{}", reply.markdown);
    }

    /// Tapping a picker button switches project / session through the SAME
    /// path `/cd` / `/use` use. A `nav:cd:<slug>` tap moves the current
    /// project; a `nav:use:<sid>` tap focuses the session (and moves the
    /// current project to that session's).
    #[tokio::test]
    async fn nav_button_tap_switches_project_and_session() {
        let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
        let proj = tempfile::TempDir::new().unwrap();
        let mut gateway = Gateway::new(fake, "alpha", proj.path());
        // The owner's own chat(s): named in the bot allowlist ⇒ operator.
        gateway.bind_operator_allowlist("telegram", ["chat-1".to_string()]);
        gateway.register_project("beta", proj.path());
        gateway
            .handle_text("telegram", "chat-1", "alice", "/new claude reviewer")
            .await
            .unwrap();
        let chat = ChatKey::new("telegram", "chat-1", "alice");

        // Tap "switch to beta".
        let replies = gateway
            .handle_message(
                "telegram",
                "chat-1",
                "alice",
                "",
                "",
                &[],
                Some(&ChoiceReply {
                    data: "nav:cd:beta".to_string(),
                    callback_ephemeral: None,
                }),
            )
            .await
            .unwrap();
        assert_eq!(
            replies,
            vec![
                "Выбран проект beta (следующее сообщение создаст там сессию)\n↓ Сессии проекта → /sessions"
            ]
        );
        assert_eq!(gateway.current_project_for(&chat).as_deref(), Some("beta"));

        // Tap "switch to s1" — focuses s1 and moves the project back to its own
        // (alpha).
        let replies = gateway
            .handle_message(
                "telegram",
                "chat-1",
                "alice",
                "",
                "",
                &[],
                Some(&ChoiceReply {
                    data: "nav:use:s1".to_string(),
                    callback_ephemeral: None,
                }),
            )
            .await
            .unwrap();
        assert_eq!(replies, vec!["Используется сессия s1\n↓ Статус → /status"]);
        assert_eq!(gateway.current_project_for(&chat).as_deref(), Some("alpha"));
        assert_eq!(
            gateway.current_session.read().unwrap().get(&chat).cloned(),
            Some("s1".to_string())
        );

        // A malformed nav payload is benign (never panics / switches).
        let replies = gateway
            .handle_message(
                "telegram",
                "chat-1",
                "alice",
                "",
                "",
                &[],
                Some(&ChoiceReply {
                    data: "nav:bogus".to_string(),
                    callback_ephemeral: None,
                }),
            )
            .await
            .unwrap();
        assert_eq!(replies, vec!["Некорректный выбор"]);
    }

