    /// v0.8.23 review §1.3-D item 9 — IM `/sessions` pins a session with an
    /// outstanding HITL approval to the top of the live list, even when it
    /// is LESS recent than its siblings. `s2` (qa) is created after `s1`
    /// (reviewer) so the default recency order is `s2` then `s1`; tagging
    /// `s1` with a pending approval must invert that. SPEC-3.5b-waiting-arm
    /// — the pin is a SORT order only, not a distinct activity icon: s1's
    /// row still reads its real classification (idle, no live turn), `🟢
    /// ожидание` — the palette has no separate `waiting` state.
    #[tokio::test]
    async fn gateway_sessions_pins_waiting_approval_to_top_with_marker() {
        let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
        let proj = tempfile::TempDir::new().unwrap();
        let mut gateway = Gateway::new(fake, "alpha", proj.path());
        let shared = Arc::new(Mutex::new(crate::pending::PendingInteractions::new()));
        gateway.set_pending(shared.clone());

        gateway
            .handle_text("mock", "chat-1", "alice", "/new claude reviewer")
            .await
            .unwrap();
        gateway
            .handle_text("mock", "chat-1", "alice", "/new claude qa")
            .await
            .unwrap();

        // No pending yet — plain recency order (s2 newer, sorts first).
        let before = gateway
            .handle_text("mock", "chat-1", "alice", "/sessions")
            .await
            .unwrap();
        assert_eq!(before.len(), 1);
        let s2 = before[0].find("s2 | claude.—").unwrap();
        let s1 = before[0].find("s1 | claude.—").unwrap();
        assert!(s2 < s1, "newer s2 remains first: {}", before[0]);

        // Tag s1 (the OLDER session) with an outstanding approval.
        let token = "pwaitpin001";
        let (tx, _rx) = tokio::sync::oneshot::channel::<ChoiceSelection>();
        shared.lock().await.register(
            token.to_string(),
            permission_prompt(token),
            InteractionOrigin::External { reply: tx },
            Instant::now() + std::time::Duration::from_secs(600),
        );
        shared.lock().await.tag_sid(token, "s1".to_string());

        let after = gateway
            .handle_text("mock", "chat-1", "alice", "/sessions")
            .await
            .unwrap();
        assert_eq!(after.len(), 1);
        let s1 = after[0].find("s1 | claude.— | 🟢 ожидание | —").unwrap();
        let s2 = after[0].find("s2 | claude.—").unwrap();
        assert!(s1 < s2, "s1 pinned to the top: {}", after[0]);
    }

