    /// v0.8.19 `/status` — fleet-health states derive deterministically from
    /// the per-session `turn_started_at` / `last_event_at` cells:
    /// - no turn in flight (`turn_started_at == None`) ⇒ 🟢 idle.
    /// - in flight + a recent event ⇒ 🔵 working (with elapsed).
    /// - in flight + last event stale past the idle window ⇒ 🔴 STUCK (matching
    ///   the watchdog's "silent for a full window" definition).
    /// Also asserts model · effort · контекст come from the real `thread_status`,
    /// and `контекст —` when no context is reported.
    #[tokio::test]
    async fn gateway_status_renders_idle_working_stuck() {
        let fake = Arc::new(FakeAdapter::new(AgentVendor::Claude));
        let mut gateway = Gateway::new(fake.clone(), "alpha", "/tmp/alpha");
        gateway
            .handle_text("mock", "chat-1", "alice", "/new claude reviewer")
            .await
            .unwrap();
        // A model + effort + context so the model·effort·контекст tail is exercised.
        fake.set_status(ThreadStatus {
            model: Some("claude-opus-4-8".into()),
            context: Some(ContextUsage::known(
                410_000,
                1_000_000,
                ContextSource::Derived,
            )),
            effort: Some("max".into()),
            goal: None,
        })
        .await;

        // (1) No turn in flight → 🟢 idle (seeded None at construction).
        let idle = gateway
            .handle_text("mock", "chat-1", "alice", "/status")
            .await
            .unwrap();
        assert_eq!(idle.len(), 1, "one message: {idle:?}");
        // /status remains the CURRENT session's card, not the fleet table.
        assert!(
            idle[0].contains("🧭 s1 · claude · claude-opus-4-8 · max\n🟢 ожидание · ctx 41%"),
            "current-session header: {idle:?}"
        );

        // (2) A turn in flight with a RECENT event → 🔵 working.
        let now = Instant::now();
        {
            let s = gateway.sessions.get("s1").expect("session s1");
            *s.turn_started_at.lock().unwrap() = Some(now);
            *s.last_event_at.lock().unwrap() = Some(now);
            *s.latest_activity.lock().unwrap() = Some("read×16·bash×8".to_string());
        }
        let working = gateway
            .handle_text("mock", "chat-1", "alice", "/status")
            .await
            .unwrap();
        assert!(
            working[0].contains("🔵 работает"),
            "working state: {working:?}"
        );
        assert!(
            working[0].contains("ctx 41%"),
            "ctx still shown: {working:?}"
        );

        // (3) In flight for a full idle window with the turn's own last event
        // just as stale → 🔴 STUCK. Use the SAME threshold the code reads so
        // the test is deterministic against any env-configured window.
        let mut window = gateway_turn_timeout_duration();
        if window.is_zero() {
            window = std::time::Duration::from_secs(300);
        }
        {
            let s = gateway.sessions.get("s1").expect("session s1");
            *s.turn_started_at.lock().unwrap() =
                Some(now - (window + std::time::Duration::from_secs(120)));
            *s.last_event_at.lock().unwrap() =
                Some(now - (window + std::time::Duration::from_secs(60)));
        }
        let stuck = gateway
            .handle_text("mock", "chat-1", "alice", "/status")
            .await
            .unwrap();
        // §3.5d — the compact line-2 badge carries just the icon + label;
        // the silent-duration phrase rides the expandable quote folded into
        // the SAME "Запущено: …" part as a comma suffix — never instead of
        // the real launch time (R1 fix: `Запущено:` used to be fed this
        // phrase directly; SPEC-3.5D-R2-2 fix: it used to ride as its own
        // extra `·`-joined part, growing the quote past the spec's four).
        assert!(stuck[0].contains("🔴 зависание"), "stuck badge: {stuck:?}");
        // review-fix F3 — the label must come FROM `activity_badge`, so a
        // future palette rename shows up here without editing this test.
        assert!(
            stuck[0].contains(&format!("🔴 {}", im_views::activity_badge("stuck").1)),
            "/status label must match the activity_badge palette: {stuck:?}"
        );
        assert!(
            stuck[0].contains("Запущено:") && stuck[0].contains("назад"),
            "an honest launch time, not the activity phrase: {stuck:?}"
        );
        assert!(
            stuck[0].contains("Запущено:") && stuck[0].contains("назад, зависание: нет событий 6m"),
            "silent duration folded into the SAME Запущено part, comma-joined: {stuck:?}"
        );
        assert_eq!(
            stuck[0].matches("Запущено:").count(),
            1,
            "exactly one Запущено part in the quote, not a second `·`-joined one: {stuck:?}"
        );

        // (4) A FRESHLY submitted turn whose `last_event_at` still holds the
        // PREVIOUS turn's last event (the pump only writes that cell) must read
        // 🔵 working, not 🔴 STUCK: silence is measured within the turn, so the
        // baseline clamps to the turn's own start.
        {
            let s = gateway.sessions.get("s1").expect("session s1");
            *s.turn_started_at.lock().unwrap() = Some(now);
            *s.last_event_at.lock().unwrap() =
                Some(now - (window + std::time::Duration::from_secs(60)));
        }
        let fresh = gateway
            .handle_text("mock", "chat-1", "alice", "/status")
            .await
            .unwrap();
        assert!(
            fresh[0].contains("🔵 работает"),
            "a just-submitted turn with a pre-turn stale event is working, not stuck: {fresh:?}"
        );
    }

