        let evt = events.try_recv().expect("expected a rendered folder page");
        assert!(evt.content.contains('📂'), "content: {}", evt.content);
        let nav = gateway
            .lock()
            .await
            .fs_nav
            .get(&chat)
            .cloned()
            .expect("fs_nav set after entering a folder");
        assert_eq!(nav.rel, std::path::PathBuf::from("child"));
